/**
 * Achan's Hidden Goods
 * --------------------
 * Achan hides a Babylonian garment and silver from the spoil, and the loss at Ai is traced to him. Stage: a camp at dusk, a tent with a hidden seam, a man and his family among the stones; a search in the dark, a fire rising, a community's grief.
 *
 * Palette 0x241810 → 0x060402 · light: dusk · hero: fire
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./joshua-kit.js.
 */

import { THREE, createScene, tent, firepit, oak, flame, person } from './joshua-kit.js';

const BG = 0x241810;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 2905724784, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents, smoke rising */
    tent(W, group, -18.2, 0, -19.2, 1.38, 0xa8704a, W.r() * 6);
    tent(W, group, 7.1, 0, -7.0, 1.00, 0x8a6a44, W.r() * 6);
    tent(W, group, 8.2, 0, -11.6, 1.30, 0xc8b088, W.r() * 6);
    tent(W, group, 4.6, 0, -6.8, 1.30, 0xd8c8a0, W.r() * 6);
    firepit(W, group, -3.6, 0, -1.6, 1.0);

    /* hero: the burning bush */
    oak(W, group, 0, 0, 0, 0.75, { leaf: 0x3a4a20, leaf2: 0x4a5a28 });
    flame(W, group, 0, 1.4, 0, 1.0);
    W.point(0xff8a30, 2.4, 60, 0, 3, 0, 0.4);
    W.disc([0, 6, -12], 7, 0xffa050, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x241810, ry: 0.20, s: 1.11 });

    return W.finish();
}

export default { build };
